  ('atlanta-legal-aid', 'Atlanta Legal Aid Society', 'EVICTION_LEGAL_AID', array['PUBLIC_BENEFITS']::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, '54 Ellis St NE, Atlanta, GA 30303', '404-524-5811', 'https://atlantalegalaid.org', 'Free civil legal help for low-income residents of Fulton, DeKalb, Cobb, Gwinnett, and Clayton counties, including eviction defense and housing conditions.', 'Call your county''s intake line — Fulton 404-524-5811, DeKalb 404-377-0701, Cobb 770-528-2565, Gwinnett 678-376-4545, Clayton 404-669-0233. Have your court papers and lease ready.', 'OPEN', '2026-10-10', null, false, false),
  ('avlf-safe-stable-homes', 'Atlanta Volunteer Lawyers Foundation — Safe & Stable Homes', 'EVICTION_LEGAL_AID', array[]::text[], array['Fulton']::text[], null, null, '404-521-0790', 'https://avlf.org/housingintake/', 'Volunteer attorneys help Fulton County tenants with eviction defense and unsafe housing conditions, including through the Housing Court Assistance Center.', 'Complete the online housing intake or call; tell them your court date if you have one.', 'OPEN', '2026-10-10', null, false, false),
  ('georgia-legal-aid-org', 'GeorgiaLegalAid.org — Self-Help Library', 'EVICTION_LEGAL_AID', array[]::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, null, 'https://www.georgialegalaid.org', 'Free plain-language guides and court forms about Georgia evictions (dispossessory cases), answering a case, and tenant rights. Available to anyone.', 'Browse online — no application needed.', 'OPEN', '2026-10-10', null, false, false),
  ('ga-dca-rental', 'Georgia Department of Community Affairs — Housing Assistance', 'RENTAL_ASSISTANCE', array[]::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, '404-679-4840', 'https://dca.georgia.gov', 'State housing programs for low- and moderate-income Georgians, including Housing Choice Vouchers and homelessness assistance. There is no statewide emergency rental program open right now; check for new funding.', 'Check the DCA website for currently open programs. Housing Choice Voucher helpline: 470-802-4707.', 'UNKNOWN', '2026-10-10', 0, false, false),
  ('atlanta-housing-community-dev', 'City of Atlanta — Housing Help Center', 'RENTAL_ASSISTANCE', array['AFFORDABLE_HOUSING','MOVING_ASSISTANCE']::text[], array['Fulton','DeKalb']::text[], null, '2 Peachtree St, 1st Floor, Atlanta, GA 30303', '404-492-7640', 'https://www.housinghelpcenter.com', 'City-run help for Atlanta residents: referrals for rent and utility assistance, relocation help, legal aid, and eviction diversion. Prioritizes households at or below 60% of area median income within city limits.', 'Call, dial 3-1-1, or visit the center in person.', 'FUNDS_LIMITED', '2026-10-10', 800, false, false),
  ('fulton-emergency-rental', 'Fulton County Community Development — Homelessness Prevention', 'RENTAL_ASSISTANCE', array[]::text[], array['Fulton']::text[], null, '141 Pryor St SW, Atlanta, GA 30303', '404-612-4000', 'https://www.fultoncountyga.gov/inside-fulton-county/fulton-county-departments/community-development/housing-and-urban-development-funded-programs', 'Federally funded homelessness prevention and rapid re-housing through county partner agencies. Residents of Roswell, Sandy Springs, South Fulton, and Johns Creek are served by their own city programs instead.', 'Call 2-1-1 or the department to be referred to a partner agency with open funds.', 'UNKNOWN', '2026-10-10', 1000, false, false),
  ('dekalb-community-dev', 'DeKalb County Community Development — Housing Assistance', 'RENTAL_ASSISTANCE', array[]::text[], array['DeKalb']::text[], null, null, '404-371-2727', 'https://dekalbcountyga.gov/departments/community-development', 'DeKalb residents with low incomes may qualify for county housing assistance programs and homeless services through DeKalb''s Coordinated Entry system.', 'Check the website for open application windows. For homelessness or housing crises, call DeKalb Coordinated Entry at 404-687-3500.', 'WAITLIST', '2026-10-10', 900, false, false),
  ('cobb-community-dev', 'Cobb County CDBG Program Office — Homelessness Prevention', 'RENTAL_ASSISTANCE', array[]::text[], array['Cobb']::text[], null, '192 Anderson St, Suite 150, Marietta, GA 30060', '770-528-1455', 'https://findhelp.cobbcounty.gov', 'Cobb County residents may qualify for federally funded homelessness prevention help (rent and deposits) through the county''s partner agencies.', 'Call 2-1-1 or the CDBG Program Office for current partner agencies.', 'UNKNOWN', '2026-10-10', 700, false, false),
  ('homefirst-gwinnett', 'Gwinnett Coordinated Entry — Latin American Association Outreach Center', 'RENTAL_ASSISTANCE', array['TEMPORARY_HOUSING']::text[], array['Gwinnett']::text[], null, '5320 Jimmy Carter Blvd, Norcross, GA 30093', '678-205-1018', 'https://thelaa.org/gwinnett/', 'Gwinnett''s housing crisis assessment center for households at risk of or experiencing homelessness. Referrals for rent and utility help when funds are available.', 'Call or visit for a Coordinated Entry assessment. You can also call 2-1-1 or Gwinnett OneStop 4 Help.', 'UNKNOWN', '2026-10-10', 800, false, false),
  ('clayton-cccsa', 'Clayton County Community Services Authority', 'UTILITY_ASSISTANCE', array['FOOD_ASSISTANCE']::text[], array['Clayton']::text[], null, '1000 Main St, Forest Park, GA 30297', '404-363-0575', 'https://claytoncountycsa.org', 'Clayton County residents with low incomes may qualify for utility help (LIHEAP) and food assistance. Rental assistance is not available at this time.', 'Call Mon–Fri 8:30–4:30 and press 2 for rent, mortgage, utilities, food, and LIHEAP. A case manager assigns help — the agency does not take online applications.', 'UNKNOWN', '2026-10-10', null, false, false),
  ('salvation-army-atlanta', 'The Salvation Army — Metro Atlanta', 'RENTAL_ASSISTANCE', array['UTILITY_ASSISTANCE','FOOD_ASSISTANCE']::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, '404-486-2888', 'https://www.salvationarmyusa.org/usa-southern-territory/georgia/metro-atlanta-area-command/financial-emergency-services/', 'Emergency financial help with rent, utilities (including Project SHARE energy assistance), and food through Financial Emergency Services Centers in every metro county.', 'Call to schedule an appointment at your nearest center: Atlanta (Fulton), Decatur (DeKalb), Marietta (Cobb), Lawrenceville (Gwinnett), or Jonesboro (Clayton).', 'OPEN', '2026-10-10', 400, true, false),
  ('svdp-georgia', 'St. Vincent de Paul Georgia', 'RENTAL_ASSISTANCE', array['UTILITY_ASSISTANCE']::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, '678-892-6163', 'https://svdpgeorgia.org/get-help/', 'Neighbor-to-neighbor help with rent and utilities through local parish groups, as funds allow.', 'Call the Assistance Line and give your ZIP code — you''ll be routed to your local parish group.', 'OPEN', '2026-10-10', 350, false, false),
  ('must-ministries', 'MUST Ministries', 'RENTAL_ASSISTANCE', array['FOOD_ASSISTANCE','EMERGENCY_SHELTER','EMPLOYMENT_ASSISTANCE']::text[], array['Cobb']::text[], null, '1260 Cobb Pkwy N, Marietta, GA 30062', '770-427-9862', 'https://mustministries.org', 'Cobb County neighbors can get food, housing help, employment services, and healthcare support.', 'Call Client Services in Marietta, or the Smyrna location at 770-436-9514, for an intake appointment.', 'OPEN', '2026-10-10', 300, true, false),
  ('liheap-community-action', 'LIHEAP Energy Assistance (via local Community Action Agencies)', 'UTILITY_ASSISTANCE', array[]::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, '404-657-3426', 'https://dfcs.georgia.gov/services/low-income-home-energy-assistance-program-liheap', 'Federally funded help paying heating and cooling bills for low-income households. Seniors 65+ and homebound residents get first access each season.', 'Apply through your county''s community action agency during the open season — Partnership for Community Action (DeKalb, Gwinnett: 404-537-4300), Fulton Atlanta Community Action Authority (Fulton), Tallatoona CAP (Cobb), or Clayton County CSA (Clayton).', 'WAITLIST', '2026-10-10', null, false, false),
  ('georgia-power-assistance', 'Georgia Power — Payment Assistance & Project SHARE', 'UTILITY_ASSISTANCE', array[]::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, '888-660-5890', 'https://www.georgiapower.com/our-impact/community/giving-back/project-share.html', 'Payment arrangements, an income-qualified discount, and Project SHARE emergency energy funds for Georgia Power customers facing hardship. Some areas of Cobb and Gwinnett are served by electric co-ops instead.', 'Call customer service to request a payment arrangement. Apply for Project SHARE through The Salvation Army.', 'OPEN', '2026-10-10', null, false, false),
  ('southern-company-gas', 'Atlanta Gas Light / Gas Marketers — Assistance Programs', 'UTILITY_ASSISTANCE', array[]::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, null, 'https://www.atlantagaslight.com', 'Natural gas customers may qualify for payment plans through their gas marketer and Project SHARE emergency help. Seniors 65+ with low incomes can get a monthly discount.', 'Contact your gas marketer about payment arrangements; apply for Project SHARE through The Salvation Army.', 'UNKNOWN', '2026-10-10', null, false, false),
  ('atlanta-community-food-bank', 'Atlanta Community Food Bank', 'FOOD_ASSISTANCE', array[]::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, '404-892-3333', 'https://www.acfb.org/get-help/food-map/', 'Find free groceries at partner food pantries and community food centers across Metro Atlanta.', 'Use the online Food Finder, or text FINDFOOD to 888-976-2232, to locate a pantry near you.', 'OPEN', '2026-10-10', null, true, false),
  ('united-way-211', 'United Way of Greater Atlanta — 2-1-1', 'PUBLIC_BENEFITS', array['RENTAL_ASSISTANCE','UTILITY_ASSISTANCE','FOOD_ASSISTANCE']::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, '211', 'https://211online.unitedwayatlanta.org', 'Free, confidential help finding rent, utility, food, and other assistance programs that are currently open. Specialists answer Mon–Fri 8am–5pm; search online anytime.', 'Dial 2-1-1 (or 404-614-1000) or search online.', 'OPEN', '2026-10-10', null, false, false),
  ('georgia-gateway', 'Georgia Gateway — SNAP, Medicaid, TANF, WIC, Childcare', 'PUBLIC_BENEFITS', array['FOOD_ASSISTANCE','CHILDCARE_FAMILY']::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, '877-423-4746', 'https://gateway.ga.gov', 'Apply for food benefits (SNAP), health coverage (Medicaid), cash assistance (TANF), WIC, and CAPS childcare help. Eligibility is based on income and household size.', 'Apply online at Georgia Gateway or at your county DFCS office.', 'OPEN', '2026-10-10', null, true, false),
  ('gateway-center', 'Gateway Center', 'EMERGENCY_SHELTER', array['TEMPORARY_HOUSING','EMPLOYMENT_ASSISTANCE']::text[], array['Fulton','DeKalb']::text[], null, '275 Pryor St SW, Atlanta, GA 30303', '404-215-6600', 'https://www.gatewayctr.org', 'Front door to the City of Atlanta''s Coordinated Entry system for people experiencing homelessness — assessments, case management, and connections to shelter and permanent housing. Its own residential programs mainly serve men.', 'Call ahead to confirm intake hours, then visit.', 'OPEN', '2026-10-10', null, false, false),
  ('nicholas-house', 'Nicholas House', 'TEMPORARY_HOUSING', array['EMERGENCY_SHELTER','SECURITY_DEPOSIT_ASSISTANCE']::text[], array['Fulton','DeKalb']::text[], null, null, '404-622-0793', 'https://nicholashouse.org', 'Emergency shelter, rapid re-housing, and homelessness prevention for families with at least one child under 18 in their custody.', 'Referral through Coordinated Entry only (no walk-ins): Atlanta and Fulton through Gateway Center; DeKalb by calling 404-687-3500. For same-day shelter, call 3-1-1 in Atlanta or 2-1-1 elsewhere.', 'WAITLIST', '2026-10-10', 0, true, false),
  ('decatur-coop-ministry', 'Decatur Cooperative Ministry', 'TEMPORARY_HOUSING', array['EMERGENCY_SHELTER']::text[], array['DeKalb']::text[], null, null, null, 'https://www.decaturcooperativeministry.org', 'Hagar''s House emergency shelter (stays up to 90 days) and transitional housing across DeKalb County for families with minor children.', 'Contact the ministry to ask about current openings.', 'WAITLIST', '2026-10-10', null, true, false),
  ('rainbow-village', 'Rainbow Village', 'TEMPORARY_HOUSING', array['CHILDCARE_FAMILY']::text[], array['Gwinnett']::text[], null, '3427 Duluth Hwy, Duluth, GA 30096', '770-497-1888', 'https://www.rainbowvillage.org', 'Up to two years of housing with wraparound services for families with children experiencing homelessness, plus three years of alumni support. Not an emergency shelter.', 'Email info@rainbowvillage.org. There''s no waitlist — inquiries are considered when an apartment opens. For immediate help, call 2-1-1.', 'UNKNOWN', '2026-10-10', null, true, false),
  ('calvary-refuge', 'Calvary Refuge Center', 'EMERGENCY_SHELTER', array['TEMPORARY_HOUSING']::text[], array['Clayton','Fulton','DeKalb']::text[], null, '4265 Thurman Rd, Forest Park, GA 30297', '404-361-5309', 'https://www.calvaryrefuge.org', '21-day shelter with meals and case management for families and individuals in the south metro area. Requires a Georgia photo ID; no pets.', 'Call for a phone screening Mon–Fri 9am–1pm. Please don''t walk in.', 'UNKNOWN', '2026-10-10', null, true, false),
  ('atlanta-mission', 'Atlanta Mission', 'EMERGENCY_SHELTER', array[]::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, '404-588-4000', 'https://atlantamission.org/get-help/', 'Emergency shelter in Atlanta for men (The Shepherd''s Inn) and for women and children (Restoration House, My Sister''s House), with longer-term recovery and job-readiness programs.', 'Women and children start at Restoration House (404-588-4007); men at The Shepherd''s Inn (404-367-2493). Check admission requirements before you go.', 'OPEN', '2026-10-10', null, true, false),
  ('georgia-housing-search', 'GeorgiaHousingSearch.org', 'AFFORDABLE_HOUSING', array[]::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, '877-428-8844', 'https://www.georgiahousingsearch.org', 'Free statewide listing service for affordable rental housing, sponsored by Georgia DCA.', 'Search listings online and contact landlords directly. Call center: Mon–Fri 9am–8pm.', 'OPEN', '2026-10-10', null, false, false),
  ('atlanta-housing', 'Atlanta Housing', 'AFFORDABLE_HOUSING', array[]::text[], array['Fulton','DeKalb']::text[], null, null, '404-892-4700', 'https://www.atlantahousing.org', 'Public housing, mixed-income communities, and Housing Choice Vouchers for eligible City of Atlanta residents. Waitlists open periodically.', 'Watch the website for waitlist openings and apply online.', 'WAITLIST', '2026-10-10', null, false, false),
  ('dekalb-housing-authority', 'Housing Authority of DeKalb County', 'AFFORDABLE_HOUSING', array[]::text[], array['DeKalb']::text[], null, '246 Sycamore St, Suite 260, Decatur, GA 30030', '404-270-2500', 'https://www.dekalbhousing.org', 'Public housing and Housing Choice Vouchers for eligible DeKalb County households.', 'Apply online when waitlists are open. The office is by appointment only.', 'WAITLIST', '2026-10-10', null, false, false),
  ('marietta-housing-authority', 'Marietta Housing Authority', 'AFFORDABLE_HOUSING', array[]::text[], array['Cobb']::text[], null, '95 Cole St, Marietta, GA 30060', '770-419-3200', 'https://www.mariettahousingauthority.org', 'Housing Choice Vouchers, HUD-VASH, Family Self-Sufficiency, and affordable rental communities serving Marietta, Austell, Mableton, Powder Springs, Kennesaw, and Acworth.', 'Check the website for open waitlists.', 'UNKNOWN', '2026-10-10', null, false, false),
  ('partners-for-home-rrh', 'Partners for HOME — Rapid Re-Housing', 'SECURITY_DEPOSIT_ASSISTANCE', array['AFFORDABLE_HOUSING','MOVING_ASSISTANCE']::text[], array['Fulton','DeKalb']::text[], null, null, '311', 'https://partnersforhome.org/help/', 'Part of the City of Atlanta''s homelessness response. Rapid re-housing programs may cover deposits, first month''s rent, and short-term rental help.', 'Access through Coordinated Entry — call 3-1-1 (or 2-1-1) or visit Gateway Center.', 'FUNDS_LIMITED', '2026-10-10', 1200, false, false),
  ('metro-deposit-assistance', 'Community Deposit Assistance (via 2-1-1)', 'SECURITY_DEPOSIT_ASSISTANCE', array[]::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, '211', 'https://211online.unitedwayatlanta.org', 'Several nonprofits offer one-time help with security deposits and application fees for households moving into stable housing. 2-1-1 can tell you which are open.', 'Ask 2-1-1 (or 404-614-1000) for deposit assistance programs open in your county.', 'UNKNOWN', '2026-10-10', 500, false, false),
  ('furniture-bank-atlanta', 'Furniture Bank of Metro Atlanta', 'MOVING_ASSISTANCE', array[]::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, '2179 Bouldercrest Rd SE, Atlanta, GA 30316', '404-355-8530', 'https://furniturebankatlanta.org/get-help/', 'Free furniture for people moving out of homelessness, fleeing domestic violence, or living with HIV/AIDS. Delivery beyond 25 miles costs $50. Wait times may be longer than usual.', 'Referral only — ask your case manager, shelter, or social worker to refer you. No drop-ins.', 'OPEN', '2026-10-10', null, true, false),
  ('goodwill-north-georgia', 'Goodwill of North Georgia — Career Centers', 'WORKFORCE_DEVELOPMENT', array['EMPLOYMENT_ASSISTANCE']::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, '404-420-9900', 'https://www.goodwillng.org', 'Free job search help, résumé support, hiring events, and short-term training in IT and skilled trades. Metro career centers are in Fulton and DeKalb, plus a Mobile Career Center.', 'Visit a career center or register online for services.', 'OPEN', '2026-10-10', null, false, false),
  ('worksource-atlanta', 'WorkSource Georgia (City of Atlanta, Fulton, DeKalb, Cobb, Atlanta Regional)', 'WORKFORCE_DEVELOPMENT', array[]::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, null, 'https://www.tcsg.edu/worksource/', 'Federally funded (WIOA) job training scholarships, career coaching, and supportive services for job seekers and laid-off workers.', 'Find your local WorkSource office and attend an orientation. Gwinnett and Clayton residents use WorkSource Atlanta Regional (404-463-3327).', 'OPEN', '2026-10-10', null, false, false),
  ('georgia-dol', 'Georgia Department of Labor — Career Centers & Unemployment', 'EMPLOYMENT_ASSISTANCE', array[]::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, '877-709-8185', 'https://dol.georgia.gov', 'File for unemployment benefits if your hours or job were cut, and use free job search services through the WorkSource Georgia portal.', 'File a claim through the MyUI Claimant Portal and register in the WorkSource Georgia portal (required, or benefits may be delayed). Visit a career center for in-person help.', 'OPEN', '2026-10-10', null, false, false),
  ('urban-league-atlanta', 'Urban League of Greater Atlanta', 'EMPLOYMENT_ASSISTANCE', array['WORKFORCE_DEVELOPMENT']::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, '230 Peachtree St NE, Suite 2600, Atlanta, GA 30303', '404-659-1150', 'https://ulgatl.org', 'Workforce training, job placement, and financial coaching for adults and young adults across Metro Atlanta.', 'Register online for programs and weekly orientations. Office visits are by appointment.', 'UNKNOWN', '2026-10-10', null, false, false),
  ('ga-caps', 'Georgia CAPS Childcare Subsidy (DECAL)', 'CHILDCARE_FAMILY', array[]::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, '833-442-2277', 'https://caps.decal.ga.gov/en/', 'Helps families with low incomes pay for childcare. Families must be in a priority group (which includes families without stable housing), and most parents need 24+ hours a week of work or school.', 'Apply online through the CAPS portal or Georgia Gateway.', 'OPEN', '2026-10-10', null, true, false),
  ('chris-180', 'CHRIS 180', 'CHILDCARE_FAMILY', array['TEMPORARY_HOUSING']::text[], array['Fulton','DeKalb','Clayton','Gwinnett']::text[], null, '1030 Fayetteville Rd, Atlanta, GA 30316', '404-486-9034', 'https://chris180.org', 'Counseling for children, youth, and families who have experienced trauma, plus housing and a drop-in center for young people facing homelessness.', 'Call the main line to be connected with the right program.', 'OPEN', '2026-10-10', null, true, false),
  ('ymca-metro-atlanta', 'YMCA of Metro Atlanta — Family Support & Childcare', 'CHILDCARE_FAMILY', array[]::text[], array['Fulton','DeKalb','Cobb','Gwinnett','Clayton']::text[], null, null, '404-588-9622', 'https://www.ymcaatlanta.org', 'Early learning, afterschool, and camp programs, with financial assistance available.', 'Contact your local branch and ask about financial assistance.', 'UNKNOWN', '2026-10-10', null, true, false)
